arguments.newString:
/**
 * Получить список всех активных fiddId (инстансов)
 */
export async function getActiveFiddIds(): Promise<string[]> {
  try {
    // В openapi.yaml путь к instances не имеет префикса /api/v1/
    // поэтому запрашиваем его напрямую через прокси
    const response = await fetch('/instances');
    if (!response.ok) {
      throw new Error('Failed to fetch instances');
    }
    const ids = await response.json();
    return ids;
  } catch {
    return [];
  }
}

