{"content":"import React, { useEffect, useState } from 'react';
import ReactPlayer from 'react-player';

interface M3uPlayerProps {
  url: string; // URL к самому m3u файлу
  fiddId: string;
  messageNumber: string;
}

const M3uPlayer = ({ url, fiddId, messageNumber }: M3uPlayerProps) => {
  const [urls, setUrls] = useState<string[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Скачиваем и парсим m3u файл
    fetch(url)
      .then((res) => {
        if (!res.ok) throw new Error('Не удалось загрузить плейлист');
        return res.text();
      })
      .then((text) => {
        // Разбиваем текст по строкам
        const lines = text.split('\n');
        const parsedUrls: string[] = [];

        lines.forEach((line) => {
          const trimmed = line.trim();
          // Пропускаем пустые строки и комментарии M3U (#)
          if (!trimmed || trimmed.startsWith('#')) return;

          // Если путь относительный (не http) - достраиваем путь к локальному порту 4198
          let finalUrl = trimmed;
          if (!trimmed.startsWith('http')) {
            finalUrl = `/fidds/v1/${fiddId}/${messageNumber}/${encodeURIComponent(trimmed)}`;
          }
          parsedUrls.push(finalUrl);
        });

        if (parsedUrls.length > 0) {
          setUrls(parsedUrls);
        } else {
          setError('Плейлист пуст');
        }
      })
      .catch((e) => setError(e.message));
  }, [url, fiddId, messageNumber]);

  if (error) {
    return <div className="p-4 bg-red-100 text-red-500 rounded my-4">Ошибка плейлиста: {error}</div>;
  }

  if (urls.length === 0) {
    return <div className="p-4 bg-gray-100 rounded my-4">Загрузка плейлиста...</div>;
  }

  const handleEnded = () => {
    // Включаем следующее видео, если оно есть
    if (currentIndex < urls.length - 1) {
      setCurrentIndex(currentIndex + 1);
    }
  };

  return (
    <div className="my-4 rounded-lg overflow-hidden bg-black flex flex-col">
      <div className="p-2 bg-gray-900 text-white text-xs flex justify-between">
        <span>M3U Плейлист</span>
        <span>Трек {currentIndex + 1} из {urls.length}</span>
      </div>
      <ReactPlayer
        url={urls[currentIndex]}
        controls={true}
        width="100%"
        height="auto"
        playing={true} // Автоплей при переключении
        onEnded={handleEnded}
      />

      {/* Маленькое меню навигации */}
      {urls.length > 1 && (
        <div className="flex bg-gray-800 p-2 gap-2 overflow-x-auto">
          {urls.map((u, i) => (
            <button
              key={i}
              onClick={() => setCurrentIndex(i)}
              className={`px-3 py-1 rounded text-xs ${
                i === currentIndex ? 'bg-blue-500 text-white' : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
              }`}
            >
              № {i + 1}
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

export default M3uPlayer;","filePath":"C:\Users\HP\Downloads\SPA\habr-spa\src\components\M3uPlayer.tsx"}

