$content = @'
import { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getAllPosts } from '../services/fiddApi';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import type { Post } from '../types/Post';

const PostPage = () => {
  const { id } = useParams<{ id: string }>();
  const [post, setPost] = useState<Post | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    getAllPosts(20)
      .then(posts => {
        const found = posts.find(p => p.id === id);
        if (found) setPost(found);
        else setError('Пост не найден');
      })
      .catch(e => setError(e.message || 'Ошибка загрузки'))
      .finally(() => setLoading(false));
  }, [id]);

  if (loading) return <div className="text-center text-gray-500 mt-8">Загрузка...</div>;
  if (error) return <div className="text-center text-red-500 mt-8">{error}</div>;
  if (!post) return null;

  const isDirectory = !post.content && post.files && post.files.length > 0;
  const [fiddId, messageNumber] = post.id.split('_');

  const getFileIconSvg = (filename: string) => {
    const isFolder = !filename.includes('.');
    if (isFolder) {
      return (
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
          <rect x="3" y="6" width="18" height="12" rx="3" fill="transparent" />
          <path d="M3 12h18" />
          <path d="M6 15h3" />
        </svg>
      );
    }
    return (
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M14 3v4a1 1 0 0 0 1 1h4" />
        <path d="M17 21H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h7l5 5v11a2 2 0 0 1-2 2z" />
        <path d="M9 13h6" />
        <path d="M9 17h3" />
      </svg>
    );
  };

  const directoryList = (
    <div className="bg-white rounded-[16px] shadow-[0_4px_12px_-2px_rgba(0,0,0,0.08)] border border-gray-100 p-6 w-full font-sans">
      <div className="flex items-center justify-between mb-5">
        <h3 className="text-[22px] font-medium text-black tracking-tight">Директория</h3>
        <svg className="w-5 h-5 text-black" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" d="M5 15l7-7 7 7" />
        </svg>
      </div>

      <div className="flex flex-col gap-4 mb-3 max-h-[60vh] overflow-y-auto custom-scrollbar">
        {post.files?.map(file => {
          const fileUrl = `/fidds/v1/${fiddId}/${messageNumber}/${encodeURIComponent(file)}`;
          const isFolder = !file.includes('.');
          return (
            <a 
              key={file} 
              href={fileUrl} 
              target="_blank" 
              rel="noopener noreferrer"
              className="flex text-left items-start justify-between group cursor-pointer"
            >
              <div className="flex items-start gap-3 overflow-hidden">
                <div className="text-black flex-shrink-0 mt-0.5">
                  {getFileIconSvg(file)}
                </div>
                <span className="text-[14px] font-medium text-black leading-snug line-clamp-2 break-words max-w-[200px]">{file}</span>
              </div>
              {isFolder && (
                <svg className="w-5 h-5 text-black flex-shrink-0 ml-2 mt-0.5" fill="none" stroke="currentColor" strokeWidth="1.5" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
                </svg>
              )}
            </a>
          );
        })}
      </div>

      <div className="border-t border-gray-300 mt-4 pt-4">
        <button className="w-full text-center text-[#8C8C8C] text-[16px] font-medium hover:text-gray-900 transition-colors">
          Открыть локально
        </button>
      </div>
    </div>
  );

  return (
    <div className={`max-w-6xl mx-auto flex flex-col-reverse md:flex-row gap-6 mt-8 px-4 items-start pb-12 ${isDirectory ? 'justify-center' : ''}`}>

      <article className={`flex-1 w-full bg-white rounded-xl shadow-md p-8 min-w-0 ${isDirectory ? 'max-w-3xl' : ''}`}>
        <h1 className="text-3xl font-bold mb-4 text-gray-900">{post.title}</h1>
        <div className="flex items-center gap-2 text-xs mb-6 text-gray-500">
          <span className="font-bold text-gray-700">@{post.author}</span>
          <span>●</span>
          <span>{post.createdAt}</span>
        </div>

        {isDirectory ? (
          <div className="mt-8 flex justify-center">
            {/* Панель директории ставится прямо по центру в отсутствии текста */}
            <div className="w-full max-w-sm">
              {directoryList}
            </div>
          </div>
        ) : (
          <div className="prose max-w-none break-words overflow-hidden">
            <ReactMarkdown 
              remarkPlugins={[remarkGfm]}
              components={{
              p: ({node, children, ...props}) => {
                return <div className="my-2" {...props}>{children}</div>;
              },
              pre: ({node, ...props}) => <pre className="whitespace-pre-wrap break-words overflow-x-auto bg-gray-100 p-4 rounded-lg my-4" {...props} />,
              img: ({node, src, alt, ...props}) => {
                if (!src) return null;

                let fullSrc = src;
                if (!src.startsWith('http')) {
                  fullSrc = `/fidds/v1/${fiddId}/${messageNumber}/${encodeURIComponent(src)}`;
                }

                const ext = src.split('.').pop()?.toLowerCase();
                if (ext === 'mp4' || ext === 'webm' || ext === 'ogg' || ext === 'mov') {
                  return (
                    <div className="my-4 rounded-lg overflow-hidden bg-black">
                      <video controls src={fullSrc} className="w-full h-auto" />
                    </div>
                  );
                }
                if (ext === 'mp3' || ext === 'wav') {
                  return (
                    <div className="my-4">
                      <audio controls src={fullSrc} className="w-full" />
                    </div>
                  );
                }

                return <img src={fullSrc} alt={alt} className="rounded-lg my-4 max-w-full" {...props} />;
              }}}
          >
            {post.content}
          </ReactMarkdown>
        </div>
      )}
    </article>

    {!isDirectory && post.files && post.files.length > 0 && (
      <aside className="w-full md:w-80 flex-shrink-0">
        <div className="sticky top-8">
          {directoryList}
        </div>
      </aside>
    )}
  </div>
  );
};

export default PostPage;
